    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: 4px;
}

.nav-cta::after {
    display: none;
}

.nav-icons {
    display: flex;
    gap: var(--spacing-md);
}

.icon-btn {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--text-color);
    padding: var(--spacing-xs);
    display: flex;
    align-items: center;
    justify-content: center;
