/* Footer */
.footer {
    background-color: var(--primary-color);
    color: var(--secondary-color);
    padding: var(--spacing-xl) 0;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-xl);
}

.footer-column h4 {
    color: var(--secondary-color);
    margin-bottom: var(--spacing-md);
}

.footer-column ul {
    list-style: none;
}

.footer-column a {
    color: #ccc;
    text-decoration: none;
    transition: var(--transition);
    display: block;
    margin-bottom: var(--spacing-sm);
}

.footer-column a:hover {
    color: var(--accent-color);
}

.footer-bottom {
    text-align: center;
    padding-top: var(--spacing-lg);
    border-top: 1px solid #444;
    color: #999;
}

/* Responsive Design */
@media (max-width: 768px) {
    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    .nav-menu {
        gap: var(--spacing-md);
        font-size: 0.9rem;
    }

    .hero {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
        padding: var(--spacing-lg);
    }

    .hero-title {
        font-size: 2rem;
    }

    .hero-image {
        height: 300px;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
        gap: var(--spacing-md);
    }

    .product-image {
        height: 200px;
    }

    .deals-carousel {
        grid-template-columns: 1fr;
    }

    .deal-card {
        min-width: unset;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input {
        min-width: unset;
    }
}

@media (max-width: 480px) {
    .container {
        padding: 0 var(--spacing-sm);
    }

    h1 {
        font-size: 1.5rem;
    }

    h2 {
        font-size: 1.25rem;
    }

    .nav-container {
        padding: 0 var(--spacing-sm);
        gap: var(--spacing-sm);
    }

    .nav-menu {
        display: none;
    }

    .hero {
        padding: var(--spacing-md);
    }

    .hero-title {
        font-size: 1.5rem;
    }

    .products-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .categories-grid {
        grid-template-columns: 1fr;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }
}
