// Page Component
const PageComponent = {
    mounted: false,

    mount() {
        if (this.mounted) return;

        this.renderFeaturedProducts();
        this.renderDeals();
        this.renderArticles();
        this.attachEventListeners();

        this.mounted = true;
    },

    renderFeaturedProducts() {
        const container = document.getElementById('featured-grid');
        if (!container) return;

        container.innerHTML = store.featuredProducts
