                this.showNotification(`Browsing ${dealTitle}...`);
            });
        });

        // Newsletter form
        const newsletterForm = document.getElementById('newsletter-form');
        if (newsletterForm) {
            newsletterForm.addEventListener('submit', (e) => {
                e.preventDefault();
                const email = newsletterForm.querySelector('input[type="email"]').value;
                this.showNotification(`Thanks for subscribing! Check ${email} for confirmation.`);
                newsletterForm.reset();
            });
        }

        // Icon buttons
        document.querySelectorAll('.icon-btn').forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.preventDefault();
                const ariaLabel = btn.getAttribute('aria-label');
                if (ariaLabel === 'Cart') {
                    this.showNotification('Shopping cart opened');
                } else if (ariaLabel === 'Search') {
                    this.showNotification('Search opened');
                } else if (ariaLabel === 'Account') {
                    this.showNotification('Account menu opened');
                }
            });
        });

        // Article links
        document.querySelectorAll('.article-link').forEach(link => {
