/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --primary-color: #1a1a1a;
    --secondary-color: #ffffff;
    --accent-color: #d4af37;
    --text-color: #333333;
    --light-gray: #f5f5f5;
    --border-color: #e0e0e0;
    --success-color: #27ae60;
    --warning-color: #e67e22;
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --transition: all 0.3s ease;
    --shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.15);
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    color: var(--text-color);
    background-color: var(--secondary-color);
    line-height: 1.6;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    font-weight: 600;
    line-height: 1.2;
    color: var(--primary-color);
}

h1 {
    font-size: 3rem;
}

h2 {
    font-size: 2rem;
}

h3 {
    font-size: 1.5rem;
}

p {
    color: #666;
    margin-bottom: var(--spacing-md);
}

/* Container */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--spacing-sm) var(--spacing-md);
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    text-decoration: none;
}

.btn-primary {
    background-color: var(--primary-color);
    color: var(--secondary-color);
}

.btn-primary:hover {
    background-color: #333;
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}

.btn-large {
    padding: var(--spacing-md) var(--spacing-lg);
    font-size: 1.1rem;
}

.btn-secondary {
    background-color: var(--light-gray);
    color: var(--primary-color);
    border: 1px solid var(--border-color);
}

.btn-secondary:hover {
    background-color: #e0e0e0;
}

/* Header/Navigation */
.header {
    position: sticky;
    top: 0;
    z-index: 100;
    background-color: var(--secondary-color);
    border-bottom: 1px solid var(--border-color);
}

.navbar {
    padding: var(--spacing-md) 0;
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--primary-color);
    letter-spacing: 1px;
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
    flex: 1;
    justify-content: center;
}

.nav-menu a {
    text-decoration: none;
    color: var(--text-color);
    font-weight: 500;
    transition: var(--transition);
    position: relative;
}

.nav-menu a::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--accent-color);
    transition: width 0.3s ease;
}

.nav-menu a:hover::after {
    width: 100%;
}

.nav-cta {
    background-color: var(--primary-color);
    color: var(--secondary-color);
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: 4px;
}

.nav-cta::after {
    display: none;
}

.nav-icons {
    display: flex;
    gap: var(--spacing-md);
}

.icon-btn {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--text-color);
    padding: var(--spacing-xs);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition);
}

.icon-btn:hover {
    color: var(--accent-color);
    transform: scale(1.1);
}

/* Hero Section */
.hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-xl);
    align-items: center;
    padding: var(--spacing-xl) var(--spacing-lg);
    max-width: 1200px;
    margin: 0 auto;
}

.hero-content {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.hero-title {
    font-size: 3rem;
    line-height: 1.1;
}

.hero-subtitle {
    font-size: 1.25rem;
    color: #666;
}

.hero-image {
    height: 500px;
}

.placeholder-image {
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, #f5f5f5 0%, #e0e0e0 100%);
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1rem;
}

.placeholder-image::after {
    content: 'Image Placeholder';
}

/* Sections */
.featured-products,
.deals-section,
.category-showcase,
.editorial-content {
    padding: var(--spacing-xl) 0;
}

.featured-products {
    background-color: var(--secondary-color);
}

.deals-section {
    background-color: #fafafa;
}

.editorial-content {
    background-color: var(--secondary-color);
}

.section-header {
    text-align: center;
    margin-bottom: var(--spacing-xl);
}

.section-header h2 {
    margin-bottom: var(--spacing-sm);
}

.section-title {
    text-align: center;
    margin-bottom: var(--spacing-xl);
}

/* Products Grid */
.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background-color: var(--secondary-color);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
    box-shadow: var(--shadow);
}

.product-card:hover {
    transform: translateY(-8px);
    box-shadow: var(--shadow-lg);
}

.product-image {
    width: 100%;
    height: 300px;
    background: linear-gradient(135deg, #f5f5f5 0%, #e0e0e0 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

.product-image::after {
    content: 'Product Image';
    color: #999;
}

.product-badge {
    position: absolute;
    top: var(--spacing-sm);
    right: var(--spacing-sm);
    background-color: var(--accent-color);
    color: var(--primary-color);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: 4px;
    font-size: 0.85rem;
    font-weight: 600;
}

.product-info {
    padding: var(--spacing-md);
}

.product-name {
    font-size: 1rem;
    font-weight: 600;
    margin-bottom: var(--spacing-xs);
}

.product-category {
    color: #999;
    font-size: 0.85rem;
    margin-bottom: var(--spacing-sm);
}

.product-price {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-md);
}

.price-current {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--primary-color);
}

.price-original {
    font-size: 0.9rem;
    color: #999;
    text-decoration: line-through;
}

.product-rating {
    color: #ffc107;
    font-size: 0.9rem;
    margin-bottom: var(--spacing-md);
}

.product-btn {
    width: 100%;
    background-color: var(--primary-color);
    color: var(--secondary-color);
}

.product-btn:hover {
    background-color: #333;
}

/* Deals Carousel */
.deals-carousel {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    overflow-x: auto;
    padding-bottom: var(--spacing-md);
}

.deal-card {
    background: linear-gradient(135deg, #fff9e6 0%, #fff3d9 100%);
    padding: var(--spacing-lg);
    border-radius: 8px;
    text-align: center;
    flex-shrink: 0;
    min-width: 280px;
    box-shadow: var(--shadow);
    transition: var(--transition);
}

.deal-card:hover {
    transform: scale(1.05);
    box-shadow: var(--shadow-lg);
}

.deal-discount {
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--warning-color);
    margin-bottom: var(--spacing-sm);
}

.deal-title {
    font-size: 1.2rem;
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
}

.deal-expires {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: var(--spacing-md);
}

.deal-btn {
    width: 100%;
}

/* Category Showcase */
.categories-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
}

.category-card {
    position: relative;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: var(--transition);
}

.category-image {
    width: 100%;
    height: 400px;
}

.category-card h3 {
    position: absolute;
    bottom: var(--spacing-lg);
    left: var(--spacing-lg);
    color: var(--secondary-color);
    font-size: 2rem;
    z-index: 10;
    text-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.category-card::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.2);
    transition: var(--transition);
    z-index: 5;
}

.category-card:hover::after {
    background: rgba(0, 0, 0, 0.4);
}

/* Editorial Grid */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: var(--spacing-lg);
}

.article-card {
    background-color: var(--secondary-color);
    border-radius: 8px;
    overflow: hidden;
    box-shadow: var(--shadow);
    transition: var(--transition);
}

.article-card:hover {
    transform: translateY(-8px);
    box-shadow: var(--shadow-lg);
}

.article-image {
    width: 100%;
    height: 250px;
    background: linear-gradient(135deg, #f5f5f5 0%, #e0e0e0 100%);
}

.article-content {
    padding: var(--spacing-md);
}

.article-category {
    color: var(--accent-color);
    font-size: 0.85rem;
    font-weight: 600;
    text-transform: uppercase;
    margin-bottom: var(--spacing-sm);
}

.article-title {
    font-size: 1.2rem;
    font-weight: 600;
    margin-bottom: var(--spacing-sm);
    color: var(--primary-color);
}

.article-excerpt {
    color: #666;
    font-size: 0.95rem;
    margin-bottom: var(--spacing-md);
    line-height: 1.5;
}

.article-date {
    color: #999;
    font-size: 0.85rem;
}

.article-link {
    color: var(--primary-color);
    text-decoration: none;
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-xs);
    margin-top: var(--spacing-md);
    transition: var(--transition);
}

.article-link:hover {
    color: var(--accent-color);
}

/* Newsletter */
.newsletter {
    background: linear-gradient(135deg, #1a1a1a 0%, #333 100%);
    padding: var(--spacing-xl) 0;
    color: var(--secondary-color);
}

.newsletter-content {
    text-align: center;
}

.newsletter h2 {
    color: var(--secondary-color);
    margin-bottom: var(--spacing-md);
}

.newsletter p {
    color: #ccc;
    margin-bottom: var(--spacing-lg);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    justify-content: center;
    flex-wrap: wrap;
    max-width: 600px;
    margin: 0 auto;
}

.newsletter-form input {
    flex: 1;
    min-width: 200px;
    padding: var(--spacing-sm) var(--spacing-md);
    border: none;
    border-radius: 4px;
    font-size: 1rem;
}

.newsletter-form button {
    padding: var(--spacing-sm) var(--spacing-lg);
    background-color: var(--accent-color);
    color: var(--primary-color);
    font-weight: 600;
    transition: var(--transition);
}

.newsletter-form button:hover {
    background-color: #e6c200;
    transform: translateY(-2px);
}

/* Footer */
.footer {
    background-color: var(--primary-color);
    color: var(--secondary-color);
    padding: var(--spacing-xl) 0;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-xl);
}

.footer-column h4 {
    color: var(--secondary-color);
    margin-bottom: var(--spacing-md);
}

.footer-column ul {
    list-style: none;
}

.footer-column a {
    color: #ccc;
    text-decoration: none;
    transition: var(--transition);
    display: block;
    margin-bottom: var(--spacing-sm);
}

.footer-column a:hover {
    color: var(--accent-color);
}

.footer-bottom {
    text-align: center;
    padding-top: var(--spacing-lg);
    border-top: 1px solid #444;
    color: #999;
}

/* Responsive Design */
@media (max-width: 768px) {
    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    .nav-menu {
        gap: var(--spacing-md);
        font-size: 0.9rem;
    }

    .hero {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
        padding: var(--spacing-lg);
    }

    .hero-title {
        font-size: 2rem;
    }

    .hero-image {
        height: 300px;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
        gap: var(--spacing-md);
    }

    .product-image {
        height: 200px;
    }

    .deals-carousel {
        grid-template-columns: 1fr;
    }

    .deal-card {
        min-width: unset;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form input {
        min-width: unset;
    }
}

@media (max-width: 480px) {
    .container {
        padding: 0 var(--spacing-sm);
    }

    h1 {
        font-size: 1.5rem;
    }

    h2 {
        font-size: 1.25rem;
    }

    .nav-container {
        padding: 0 var(--spacing-sm);
        gap: var(--spacing-sm);
    }

    .nav-menu {
        display: none;
    }

    .hero {
        padding: var(--spacing-md);
    }

    .hero-title {
        font-size: 1.5rem;
    }

    .products-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .categories-grid {
        grid-template-columns: 1fr;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }
}

