// Product Component
const ProductComponent = {
    render: (product) => {
        return `
            <div class="product-card">
                <div class="product-image">
                    ${product.badge ? `<span class="product-badge">${product.badge}</span>` : ''}
                </div>
                <div class="product-info">
                    <div class="product-category">${product.category}</div>
                    <h3 class="product-name">${product.name}</h3>
                    <div class="product-price">
                        <span class="price-current">$${product.price}</span>
                        ${product.originalPrice ? `<span class="price-original">$${product.originalPrice}</span>` : ''}
                    </div>
                    <div class="product-rating">${'★'.repeat(product.rating)}${'☆'.repeat(5 - product.rating)} (${product.reviews})</div>
                    <button class="btn product-btn">Add to Cart</button>
                </div>
            </div>
        `;
    }
};

// Deal Card Component
const DealComponent = {
    render: (deal) => {
        return `
            <div class="deal-card">
                <div class="deal-discount">${deal.discount}%</div>
                <h4 class="deal-title">${deal.title}</h4>
                <p class="deal-expires">Expires in ${deal.expiresIn}</p>
                <button class="btn btn-primary deal-btn">Shop Now</button>
            </div>
        `;
    }
};

// Article Component
const ArticleComponent = {
